/* ─── src/features/reports/pages/ReportsPage.tsx ─────────────── */
import React, { useEffect, useMemo, useState } from 'react';
import { supabase } from 'services/supabaseClient';
import { Avatar } from '../../shared/Avatar';

/* ── design tokens ───────────────────────────────────────────── */
const ORANGE = '#EA580C';
const NAVY   = '#0F172A';
const SLATE  = '#64748B';
const BORDER = '#E2E8F0';
const BG     = '#F8FAFC';
const RED    = '#DC2626';
const GREEN  = '#16A34A';
const BLUE   = '#2563EB';

const PAGE_SIZE_OPTIONS = [10, 25, 50, 100];

/* ── status styles ───────────────────────────────────────────── */
const STATUS_STYLE: Record<string, { label: string; color: string; bg: string }> = {
  pending:    { label: 'Pending',    color: '#CA8A04', bg: '#FEF9C3' },
  reviewed:   { label: 'Reviewed',   color: BLUE,      bg: '#DBEAFE' },
  resolved:   { label: 'Resolved',   color: GREEN,     bg: '#DCFCE7' },
  dismissed:  { label: 'Dismissed',  color: SLATE,     bg: BG        },
  actioned:   { label: 'Actioned',   color: RED,       bg: '#FEE2E2' },
};
const stS = (s: string) => STATUS_STYLE[s?.toLowerCase()] ?? { label: s ?? 'Unknown', color: SLATE, bg: BG };

/* ── types ───────────────────────────────────────────────────── */
interface JobReport {
  id: string;
  job_id: string;
  reporter_id: string;
  reason: string;
  details: string | null;
  status: string;
  created_at: string;
  admin_response: string | null;
  responded_at: string | null;
  admin_id: string | null;
  /* joined */
  job_title: string;
  reporter_name: string;
  reporter_avatar: string | null;
}

interface MessageReport {
  id: string;
  message_id: string;
  reporter_id: string;
  conversation_id: string;
  attachment_url: string | null;
  reason: string;
  note: string | null;
  created_at: string;
  conversation_key: string | null;
  /* joined */
  reporter_name: string;
  reporter_avatar: string | null;
}

type Tab = 'job_reports' | 'message_reports';

/* ── helpers ─────────────────────────────────────────────────── */
const fmt = (iso: string) =>
  new Date(iso).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
const fmtTime = (iso: string) =>
  new Date(iso).toLocaleString('en-GB', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });

const capitalize = (s: string) => s ? s.charAt(0).toUpperCase() + s.slice(1).replace(/_/g, ' ') : '—';

/* ── Pagination ──────────────────────────────────────────────── */
const Pagination: React.FC<{
  page: number; totalPages: number; pageSize: number;
  totalItems: number; onPage: (p: number) => void; onPageSize: (n: number) => void;
}> = ({ page, totalPages, pageSize, totalItems, onPage, onPageSize }) => {
  const pages: (number | '…')[] = [];
  if (totalPages <= 7) {
    for (let i = 1; i <= totalPages; i++) pages.push(i);
  } else {
    pages.push(1);
    if (page > 3) pages.push('…');
    for (let i = Math.max(2, page - 1); i <= Math.min(totalPages - 1, page + 1); i++) pages.push(i);
    if (page < totalPages - 2) pages.push('…');
    pages.push(totalPages);
  }
  const btn: React.CSSProperties = {
    minWidth: 32, height: 32, borderRadius: 8, border: `1px solid ${BORDER}`,
    background: '#fff', fontSize: 13, fontWeight: 600, cursor: 'pointer',
    display: 'flex', alignItems: 'center', justifyContent: 'center',
    padding: '0 8px', fontFamily: 'inherit', color: NAVY,
  };
  return (
    <div style={{ padding: '14px 20px', borderTop: `1px solid #F1F5F9`, display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 10, background: BG }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
        <span style={{ fontSize: 13, color: SLATE }}>Rows per page</span>
        <select value={pageSize} onChange={e => onPageSize(Number(e.target.value))} style={{ padding: '5px 10px', borderRadius: 8, border: `1px solid ${BORDER}`, fontSize: 13, color: NAVY, background: '#fff', cursor: 'pointer', fontFamily: 'inherit', outline: 'none' }}>
          {PAGE_SIZE_OPTIONS.map(n => <option key={n} value={n}>{n}</option>)}
        </select>
        <span style={{ fontSize: 13, color: SLATE }}>
          {totalItems === 0 ? '0' : `${(page - 1) * pageSize + 1}–${Math.min(page * pageSize, totalItems)}`} of {totalItems}
        </span>
      </div>
      {totalPages > 1 && (
        <div style={{ display: 'flex', gap: 4 }}>
          <button onClick={() => onPage(page - 1)} disabled={page === 1} style={{ ...btn, opacity: page === 1 ? 0.4 : 1, cursor: page === 1 ? 'not-allowed' : 'pointer' }}>
            <svg width="13" height="13" viewBox="0 0 14 14" fill="none"><path d="M9 2L4 7l5 5" stroke={NAVY} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>
          </button>
          {pages.map((p, i) => p === '…'
            ? <span key={`e${i}`} style={{ ...btn, cursor: 'default', border: 'none', color: SLATE }}>…</span>
            : <button key={p} onClick={() => onPage(p as number)} style={{ ...btn, background: page === p ? ORANGE : '#fff', color: page === p ? '#fff' : NAVY, border: `1px solid ${page === p ? ORANGE : BORDER}` }}>{p}</button>
          )}
          <button onClick={() => onPage(page + 1)} disabled={page === totalPages} style={{ ...btn, opacity: page === totalPages ? 0.4 : 1, cursor: page === totalPages ? 'not-allowed' : 'pointer' }}>
            <svg width="13" height="13" viewBox="0 0 14 14" fill="none"><path d="M5 2l5 5-5 5" stroke={NAVY} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>
          </button>
        </div>
      )}
    </div>
  );
};

/* ── Admin Response Modal ────────────────────────────────────── */
const ResponseModal: React.FC<{
  report: JobReport;
  onClose: () => void;
  onSave: (id: string, status: string, response: string) => Promise<void>;
}> = ({ report, onClose, onSave }) => {
  const [status,   setStatus]   = useState(report.status);
  const [response, setResponse] = useState(report.admin_response ?? '');
  const [saving,   setSaving]   = useState(false);

  const handleSave = async () => {
    if (!response.trim()) return;
    setSaving(true);
    await onSave(report.id, status, response);
    setSaving(false);
    onClose();
  };

  return (
    <>
      <div onClick={onClose} style={{ position: 'fixed', inset: 0, background: 'rgba(15,23,42,0.4)', backdropFilter: 'blur(2px)', zIndex: 200 }}/>
      <div style={{ position: 'fixed', top: '50%', left: '50%', transform: 'translate(-50%,-50%)', background: '#fff', borderRadius: 16, zIndex: 201, width: 'min(520px, 94vw)', boxShadow: '0 20px 60px rgba(15,23,42,0.18)', fontFamily: "'DM Sans','Helvetica Neue',sans-serif" }}>
        {/* header */}
        <div style={{ padding: '18px 24px', borderBottom: `1px solid ${BORDER}`, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            <div style={{ fontSize: 15, fontWeight: 700, color: NAVY }}>Respond to Report</div>
            <div style={{ fontSize: 12, color: SLATE, marginTop: 2 }}>Job: <strong>{report.job_title}</strong></div>
          </div>
          <button onClick={onClose} style={{ width: 30, height: 30, borderRadius: 8, border: `1px solid ${BORDER}`, background: '#fff', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <svg width="13" height="13" viewBox="0 0 14 14" fill="none"><path d="M2 2l10 10M12 2L2 12" stroke={SLATE} strokeWidth="1.8" strokeLinecap="round"/></svg>
          </button>
        </div>

        <div style={{ padding: '20px 24px', display: 'flex', flexDirection: 'column', gap: 16 }}>
          {/* report details */}
          <div style={{ background: BG, borderRadius: 10, padding: '14px 16px', display: 'flex', flexDirection: 'column', gap: 8 }}>
            <div style={{ display: 'flex', gap: 24, flexWrap: 'wrap' }}>
              <div>
                <div style={{ fontSize: 11, fontWeight: 600, color: SLATE, textTransform: 'uppercase', letterSpacing: 0.6, marginBottom: 3 }}>Reporter</div>
                <div style={{ fontSize: 13, color: NAVY, fontWeight: 500 }}>{report.reporter_name}</div>
              </div>
              <div>
                <div style={{ fontSize: 11, fontWeight: 600, color: SLATE, textTransform: 'uppercase', letterSpacing: 0.6, marginBottom: 3 }}>Reason</div>
                <div style={{ fontSize: 13, color: NAVY, fontWeight: 500 }}>{capitalize(report.reason)}</div>
              </div>
              <div>
                <div style={{ fontSize: 11, fontWeight: 600, color: SLATE, textTransform: 'uppercase', letterSpacing: 0.6, marginBottom: 3 }}>Reported</div>
                <div style={{ fontSize: 13, color: NAVY, fontWeight: 500 }}>{fmt(report.created_at)}</div>
              </div>
            </div>
            {report.details && (
              <div>
                <div style={{ fontSize: 11, fontWeight: 600, color: SLATE, textTransform: 'uppercase', letterSpacing: 0.6, marginBottom: 3 }}>Details</div>
                <div style={{ fontSize: 13, color: SLATE, lineHeight: 1.6 }}>{report.details}</div>
              </div>
            )}
          </div>

          {/* status */}
          <div>
            <label style={{ fontSize: 12, fontWeight: 600, color: SLATE, display: 'block', marginBottom: 6 }}>Update Status</label>
            <select value={status} onChange={e => setStatus(e.target.value)} style={{ width: '100%', padding: '10px 14px', borderRadius: 10, border: `1px solid ${BORDER}`, fontSize: 14, color: NAVY, fontFamily: 'inherit', outline: 'none', background: '#fff' }}>
              {['pending', 'reviewed', 'resolved', 'dismissed', 'actioned'].map(s => (
                <option key={s} value={s}>{capitalize(s)}</option>
              ))}
            </select>
          </div>

          {/* response */}
          <div>
            <label style={{ fontSize: 12, fontWeight: 600, color: SLATE, display: 'block', marginBottom: 6 }}>Admin Response</label>
            <textarea
              value={response}
              onChange={e => setResponse(e.target.value)}
              placeholder="Write your response to this report…"
              rows={4}
              style={{ width: '100%', boxSizing: 'border-box', padding: '10px 14px', borderRadius: 10, border: `1px solid ${BORDER}`, fontSize: 14, color: NAVY, fontFamily: 'inherit', outline: 'none', resize: 'vertical', lineHeight: 1.6 }}
              onFocus={e => (e.currentTarget.style.borderColor = ORANGE)}
              onBlur={e  => (e.currentTarget.style.borderColor = BORDER)}
            />
          </div>
        </div>

        <div style={{ padding: '14px 24px', borderTop: `1px solid ${BORDER}`, display: 'flex', gap: 10, justifyContent: 'flex-end' }}>
          <button onClick={onClose} style={{ padding: '9px 20px', borderRadius: 10, border: `1px solid ${BORDER}`, background: '#fff', fontSize: 14, fontWeight: 600, color: SLATE, cursor: 'pointer', fontFamily: 'inherit' }}>Cancel</button>
          <button onClick={handleSave} disabled={saving || !response.trim()} style={{ padding: '9px 20px', borderRadius: 10, border: 'none', background: ORANGE, fontSize: 14, fontWeight: 600, color: '#fff', cursor: saving ? 'not-allowed' : 'pointer', opacity: saving ? 0.7 : 1, fontFamily: 'inherit' }}>
            {saving ? 'Saving…' : 'Submit Response'}
          </button>
        </div>
      </div>
    </>
  );
};

/* ── Detail Drawer ───────────────────────────────────────────── */
const DetailDrawer: React.FC<{ report: JobReport | MessageReport | null; type: Tab; onClose: () => void }> = ({ report, type, onClose }) => {
  if (!report) return null;
  return (
    <>
      <div onClick={onClose} style={{ position: 'fixed', inset: 0, background: 'rgba(15,23,42,0.25)', zIndex: 199 }}/>
      <div style={{ position: 'fixed', top: 0, right: 0, bottom: 0, width: 'min(420px, 100vw)', background: '#fff', zIndex: 200, boxShadow: '-8px 0 32px rgba(15,23,42,0.12)', display: 'flex', flexDirection: 'column', fontFamily: "'DM Sans','Helvetica Neue',sans-serif" }}>
        <div style={{ padding: '20px 24px', borderBottom: `1px solid ${BORDER}`, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <span style={{ fontSize: 15, fontWeight: 700, color: NAVY }}>Report Details</span>
          <button onClick={onClose} style={{ width: 30, height: 30, borderRadius: 8, border: `1px solid ${BORDER}`, background: '#fff', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <svg width="13" height="13" viewBox="0 0 14 14" fill="none"><path d="M2 2l10 10M12 2L2 12" stroke={SLATE} strokeWidth="1.8" strokeLinecap="round"/></svg>
          </button>
        </div>
        <div style={{ flex: 1, overflowY: 'auto', padding: '20px 24px', display: 'flex', flexDirection: 'column', gap: 20 }}>
          {/* reporter */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
            <Avatar src={report.reporter_avatar} name={report.reporter_name} size={44}/>
            <div>
              <div style={{ fontSize: 15, fontWeight: 700, color: NAVY }}>{report.reporter_name}</div>
              <div style={{ fontSize: 12, color: SLATE }}>Reported {fmt(report.created_at)}</div>
            </div>
          </div>

          {type === 'job_reports' ? (() => {
            const jr = report as JobReport;
            const ss = stS(jr.status);
            return (
              <>
                <Row label="Job" value={jr.job_title}/>
                <Row label="Reason" value={capitalize(jr.reason)}/>
                {jr.details && <Row label="Details" value={jr.details} multiline/>}
                <Row label="Status" value={<span style={{ padding: '3px 10px', borderRadius: 20, fontSize: 12, fontWeight: 600, background: ss.bg, color: ss.color }}>{ss.label}</span>}/>
                {jr.admin_response && (
                  <div style={{ background: '#F0FDF4', border: '1px solid #BBF7D0', borderRadius: 10, padding: '14px 16px' }}>
                    <div style={{ fontSize: 11, fontWeight: 600, color: GREEN, textTransform: 'uppercase', letterSpacing: 0.6, marginBottom: 6 }}>Admin Response</div>
                    <div style={{ fontSize: 13, color: NAVY, lineHeight: 1.7 }}>{jr.admin_response}</div>
                    {jr.responded_at && <div style={{ fontSize: 11, color: SLATE, marginTop: 8 }}>Responded {fmtTime(jr.responded_at)}</div>}
                  </div>
                )}
              </>
            );
          })() : (() => {
            const mr = report as MessageReport;
            return (
              <>
                <Row label="Reason" value={capitalize(mr.reason)}/>
                {mr.note && <Row label="Note" value={mr.note} multiline/>}
                {mr.conversation_key && <Row label="Conversation" value={mr.conversation_key}/>}
                {mr.attachment_url && (
                  <div>
                    <div style={{ fontSize: 11, fontWeight: 600, color: SLATE, textTransform: 'uppercase', letterSpacing: 0.6, marginBottom: 6 }}>Attachment</div>
                    <a href={mr.attachment_url} target="_blank" rel="noreferrer" style={{ fontSize: 13, color: BLUE, wordBreak: 'break-all' }}>View attachment ↗</a>
                  </div>
                )}
              </>
            );
          })()}
        </div>
      </div>
    </>
  );
};

const Row: React.FC<{ label: string; value: React.ReactNode; multiline?: boolean }> = ({ label, value, multiline }) => (
  <div>
    <div style={{ fontSize: 11, fontWeight: 600, color: SLATE, textTransform: 'uppercase', letterSpacing: 0.6, marginBottom: 5 }}>{label}</div>
    <div style={{ fontSize: 14, color: NAVY, lineHeight: multiline ? 1.7 : 1.4 }}>{value}</div>
  </div>
);

/* ══════════════════════════════════════════════════════════════
   MAIN PAGE
══════════════════════════════════════════════════════════════ */
const ReportsPage: React.FC = () => {
  const [tab, setTab] = useState<Tab>('job_reports');

  /* data */
  const [jobReports,     setJobReports]     = useState<JobReport[]>([]);
  const [messageReports, setMessageReports] = useState<MessageReport[]>([]);
  const [loadingJR,      setLoadingJR]      = useState(true);
  const [loadingMR,      setLoadingMR]      = useState(true);

  /* filters */
  const [search,  setSearch]  = useState('');
  const [statusF, setStatusF] = useState('all');
  const [reasonF, setReasonF] = useState('all');
  const [dateFrom,setDateFrom]= useState('');
  const [dateTo,  setDateTo]  = useState('');

  /* pagination */
  const [jrPage, setJrPage] = useState(1);
  const [jrSize, setJrSize] = useState(25);
  const [mrPage, setMrPage] = useState(1);
  const [mrSize, setMrSize] = useState(25);

  /* modals */
  const [responseTarget, setResponseTarget] = useState<JobReport | null>(null);
  const [drawerTarget,   setDrawerTarget]   = useState<JobReport | MessageReport | null>(null);

  /* ── load job_reports ───────────────────────────────────── */
  useEffect(() => {
    const load = async () => {
      const { data, error } = await supabase
        .from('job_reports')
        .select('id, job_id, reporter_id, reason, details, status, created_at, admin_response, responded_at, admin_id')
        .order('created_at', { ascending: false });

      if (error || !data) { setLoadingJR(false); return; }

      /* batch fetch jobs */
      const jobIds = Array.from(new Set(data.map((r: any) => r.job_id).filter(Boolean))) as string[];
      const { data: jobs } = await supabase
        .from('jobs')
        .select('id, title')
        .in('id', jobIds);
      const jobMap = new Map((jobs ?? []).map((j: any) => [j.id, j.title ?? 'Untitled Job']));

      /* batch fetch reporters */
      const repIds = Array.from(new Set(data.map((r: any) => r.reporter_id).filter(Boolean))) as string[];
      const { data: profiles } = await supabase
        .from('profiles')
        .select('id, first_name, last_name, image_url')
        .in('id', repIds);
      const profMap = new Map((profiles ?? []).map((p: any) => [
        p.id,
        { name: [p.first_name, p.last_name].filter(Boolean).join(' ') || 'Unknown', avatar: p.image_url ?? null },
      ]));

      setJobReports(data.map((r: any): JobReport => ({
        ...r,
        job_title:       jobMap.get(r.job_id)      ?? 'Unknown Job',
        reporter_name:   profMap.get(r.reporter_id)?.name   ?? 'Unknown',
        reporter_avatar: profMap.get(r.reporter_id)?.avatar ?? null,
      })));
      setLoadingJR(false);
    };
    load();
  }, []);

  /* ── load message_reports ───────────────────────────────── */
  useEffect(() => {
    const load = async () => {
      const { data, error } = await supabase
        .from('message_reports')
        .select('id, message_id, reporter_id, conversation_id, attachment_url, reason, note, created_at, conversation_key')
        .order('created_at', { ascending: false });

      if (error || !data) { setLoadingMR(false); return; }

      const repIds = Array.from(new Set(data.map((r: any) => r.reporter_id).filter(Boolean))) as string[];
      const { data: profiles } = await supabase
        .from('profiles')
        .select('id, first_name, last_name, image_url')
        .in('id', repIds);
      const profMap = new Map((profiles ?? []).map((p: any) => [
        p.id,
        { name: [p.first_name, p.last_name].filter(Boolean).join(' ') || 'Unknown', avatar: p.image_url ?? null },
      ]));

      setMessageReports(data.map((r: any): MessageReport => ({
        ...r,
        reporter_name:   profMap.get(r.reporter_id)?.name   ?? 'Unknown',
        reporter_avatar: profMap.get(r.reporter_id)?.avatar ?? null,
      })));
      setLoadingMR(false);
    };
    load();
  }, []);

  /* reset page on filter change */
  useEffect(() => { setJrPage(1); setMrPage(1); }, [search, statusF, reasonF, dateFrom, dateTo, tab]);

  /* ── filtered job reports ───────────────────────────────── */
  const filteredJR = useMemo(() => {
    let list = jobReports;
    if (search.trim()) {
      const q = search.toLowerCase();
      list = list.filter(r =>
        r.job_title.toLowerCase().includes(q) ||
        r.reporter_name.toLowerCase().includes(q) ||
        (r.reason ?? '').toLowerCase().includes(q) ||
        (r.details ?? '').toLowerCase().includes(q)
      );
    }
    if (statusF !== 'all') list = list.filter(r => r.status === statusF);
    if (reasonF !== 'all') list = list.filter(r => r.reason === reasonF);
    if (dateFrom) { const f = new Date(dateFrom).getTime(); list = list.filter(r => new Date(r.created_at).getTime() >= f); }
    if (dateTo)   { const t = new Date(dateTo).getTime();   list = list.filter(r => new Date(r.created_at).getTime() <= t); }
    return list;
  }, [jobReports, search, statusF, reasonF, dateFrom, dateTo]);

  /* ── filtered message reports ───────────────────────────── */
  const filteredMR = useMemo(() => {
    let list = messageReports;
    if (search.trim()) {
      const q = search.toLowerCase();
      list = list.filter(r =>
        r.reporter_name.toLowerCase().includes(q) ||
        (r.reason ?? '').toLowerCase().includes(q) ||
        (r.note ?? '').toLowerCase().includes(q) ||
        (r.conversation_key ?? '').toLowerCase().includes(q)
      );
    }
    if (reasonF !== 'all') list = list.filter(r => r.reason === reasonF);
    if (dateFrom) { const f = new Date(dateFrom).getTime(); list = list.filter(r => new Date(r.created_at).getTime() >= f); }
    if (dateTo)   { const t = new Date(dateTo).getTime();   list = list.filter(r => new Date(r.created_at).getTime() <= t); }
    return list;
  }, [messageReports, search, reasonF, dateFrom, dateTo]);

  /* ── paginated slices ───────────────────────────────────── */
  const jrTotalPages = Math.max(1, Math.ceil(filteredJR.length / jrSize));
  const mrTotalPages = Math.max(1, Math.ceil(filteredMR.length / mrSize));
  const pagedJR = filteredJR.slice((jrPage - 1) * jrSize, jrPage * jrSize);
  const pagedMR = filteredMR.slice((mrPage - 1) * mrSize, mrPage * mrSize);

  /* ── admin response save ────────────────────────────────── */
  const handleSaveResponse = async (id: string, status: string, response: string) => {
    const { error } = await supabase
      .from('job_reports')
      .update({ status, admin_response: response, responded_at: new Date().toISOString() })
      .eq('id', id);
    if (!error) {
      setJobReports(prev => prev.map(r =>
        r.id === id ? { ...r, status, admin_response: response, responded_at: new Date().toISOString() } : r
      ));
    }
  };

  /* ── stat counts ────────────────────────────────────────── */
  const pendingJR  = jobReports.filter(r => r.status === 'pending').length;
  const resolvedJR = jobReports.filter(r => r.status === 'resolved').length;
  const reasonOptsJR = Array.from(new Set(jobReports.map(r => r.reason))).sort();
  const reasonOptsMR = Array.from(new Set(messageReports.map(r => r.reason))).sort();

  /* ── table styles ───────────────────────────────────────── */
  const th: React.CSSProperties = { padding: '11px 16px', textAlign: 'left', fontSize: 11, fontWeight: 700, color: SLATE, borderBottom: `1px solid ${BORDER}`, background: BG, whiteSpace: 'nowrap', textTransform: 'uppercase', letterSpacing: 0.6 };
  const td: React.CSSProperties = { padding: '13px 16px', fontSize: 14, color: NAVY, borderBottom: '1px solid #F1F5F9', verticalAlign: 'middle' };

  const loading = tab === 'job_reports' ? loadingJR : loadingMR;

  return (
    <div style={{ fontFamily: "'DM Sans','Helvetica Neue',sans-serif", display: 'flex', flexDirection: 'column', gap: 20 }}>

      {/* page header */}
      <div>
        <h1 style={{ margin: 0, fontSize: 22, fontWeight: 800, color: NAVY }}>Reports</h1>
        <p style={{ margin: '4px 0 0', fontSize: 13, color: SLATE }}>Review and action job and message reports submitted by users</p>
      </div>

      {/* stat chips */}
      <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
        {[
          { label: 'Job Reports',      value: jobReports.length,     color: ORANGE },
          { label: 'Pending',          value: pendingJR,             color: '#CA8A04' },
          { label: 'Resolved',         value: resolvedJR,            color: GREEN },
          { label: 'Message Reports',  value: messageReports.length, color: BLUE },
        ].map(({ label, value, color }) => (
          <div key={label} style={{ background: '#fff', border: `1px solid ${BORDER}`, borderRadius: 12, padding: '12px 20px', display: 'flex', alignItems: 'center', gap: 12, flex: '1 1 140px' }}>
            <div style={{ width: 8, height: 8, borderRadius: '50%', background: color }}/>
            <span style={{ fontSize: 13, color: SLATE, fontWeight: 500 }}>{label}</span>
            <span style={{ fontSize: 20, fontWeight: 800, color: NAVY, marginLeft: 'auto' }}>{value}</span>
          </div>
        ))}
      </div>

      {/* card */}
      <div style={{ background: '#fff', border: `1px solid ${BORDER}`, borderRadius: 14, overflow: 'hidden' }}>

        {/* tabs */}
        <div style={{ display: 'flex', borderBottom: `1px solid ${BORDER}`, padding: '0 20px' }}>
          {([
            { id: 'job_reports',     label: `Job Reports (${jobReports.length})`     },
            { id: 'message_reports', label: `Message Reports (${messageReports.length})` },
          ] as { id: Tab; label: string }[]).map(t => (
            <button key={t.id} onClick={() => { setTab(t.id); setSearch(''); setStatusF('all'); setReasonF('all'); }} style={{
              padding: '14px 20px', border: 'none', background: 'none', cursor: 'pointer',
              fontSize: 14, fontFamily: 'inherit',
              fontWeight: tab === t.id ? 700 : 500,
              color: tab === t.id ? ORANGE : SLATE,
              borderBottom: tab === t.id ? `2px solid ${ORANGE}` : '2px solid transparent',
              marginBottom: -1, transition: 'all 0.15s',
            }}>{t.label}</button>
          ))}
        </div>

        {/* toolbar */}
        <div style={{ padding: '12px 20px', display: 'flex', gap: 10, alignItems: 'center', borderBottom: `1px solid ${BORDER}`, background: BG, flexWrap: 'wrap' }}>
          {/* search */}
          <div style={{ position: 'relative', flex: '1 1 200px', maxWidth: 300 }}>
            <svg style={{ position: 'absolute', left: 12, top: '50%', transform: 'translateY(-50%)', pointerEvents: 'none' }} width="14" height="14" viewBox="0 0 16 16" fill="none">
              <circle cx="7" cy="7" r="5" stroke={SLATE} strokeWidth="1.5"/>
              <path d="M11 11l3 3" stroke={SLATE} strokeWidth="1.5" strokeLinecap="round"/>
            </svg>
            <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search reports…"
              style={{ width: '100%', boxSizing: 'border-box', padding: '8px 12px 8px 34px', borderRadius: 10, border: `1px solid ${BORDER}`, fontSize: 13, color: NAVY, fontFamily: 'inherit', background: '#fff', outline: 'none' }}/>
          </div>

          {/* reason filter */}
          <select value={reasonF} onChange={e => setReasonF(e.target.value)} style={{ padding: '8px 14px', border: `1px solid ${BORDER}`, borderRadius: 10, fontSize: 13, color: NAVY, background: '#fff', fontFamily: 'inherit', outline: 'none', minWidth: 140 }}>
            <option value="all">All Reasons</option>
            {(tab === 'job_reports' ? reasonOptsJR : reasonOptsMR).map(r => (
              <option key={r} value={r}>{capitalize(r)}</option>
            ))}
          </select>

          {/* status filter — only for job reports */}
          {tab === 'job_reports' && (
            <select value={statusF} onChange={e => setStatusF(e.target.value)} style={{ padding: '8px 14px', border: `1px solid ${BORDER}`, borderRadius: 10, fontSize: 13, color: NAVY, background: '#fff', fontFamily: 'inherit', outline: 'none', minWidth: 140 }}>
              <option value="all">All Statuses</option>
              {['pending', 'reviewed', 'resolved', 'dismissed', 'actioned'].map(s => (
                <option key={s} value={s}>{capitalize(s)}</option>
              ))}
            </select>
          )}

          {/* date range */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, border: `1px solid ${BORDER}`, borderRadius: 10, padding: '6px 12px', background: '#fff' }}>
            <svg width="14" height="14" viewBox="0 0 16 16" fill="none"><rect x="1" y="3" width="14" height="12" rx="2" stroke="#94A3B8" strokeWidth="1.4"/><path d="M1 7h14M5 1v4M11 1v4" stroke="#94A3B8" strokeWidth="1.4" strokeLinecap="round"/></svg>
            <input type="date" value={dateFrom} onChange={e => setDateFrom(e.target.value)} style={{ border: 'none', outline: 'none', fontSize: 12, color: SLATE, fontFamily: 'inherit', background: 'transparent' }}/>
            <span style={{ color: '#CBD5E1' }}>–</span>
            <input type="date" value={dateTo} onChange={e => setDateTo(e.target.value)} style={{ border: 'none', outline: 'none', fontSize: 12, color: SLATE, fontFamily: 'inherit', background: 'transparent' }}/>
          </div>

          <span style={{ fontSize: 13, color: SLATE, marginLeft: 'auto' }}>
            {tab === 'job_reports' ? filteredJR.length : filteredMR.length} results
          </span>
        </div>

        {/* table */}
        {loading ? (
          <div style={{ padding: '48px 0', textAlign: 'center', color: SLATE, fontSize: 14 }}>Loading reports…</div>
        ) : (
          <>
            <div style={{ overflowX: 'auto' }}>
              {tab === 'job_reports' ? (
                <table style={{ width: '100%', borderCollapse: 'collapse', minWidth: 760 }}>
                  <thead>
                    <tr>
                      <th style={{ ...th, width: 52, textAlign: 'center' }}>#</th>
                      <th style={th}>Reporter</th>
                      <th style={th}>Job</th>
                      <th style={th}>Reason</th>
                      <th style={th}>Status</th>
                      <th style={th}>Reported</th>
                      <th style={{ ...th, textAlign: 'right' }}>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {pagedJR.length === 0 ? (
                      <tr><td colSpan={7} style={{ ...td, textAlign: 'center', color: '#94A3B8', padding: '48px 0' }}>
                        {search || statusF !== 'all' || reasonF !== 'all' ? 'No reports match your filters.' : 'No job reports yet.'}
                      </td></tr>
                    ) : pagedJR.map((r, idx) => {
                      const ss = stS(r.status);
                      return (
                        <tr key={r.id} onClick={() => setDrawerTarget(r)}
                          onMouseEnter={e => e.currentTarget.style.background = BG}
                          onMouseLeave={e => e.currentTarget.style.background = '#fff'}
                          style={{ transition: 'background 0.1s', cursor: 'pointer' }}>
                          <td style={{ ...td, textAlign: 'center', color: '#94A3B8', fontSize: 12 }}>
                            {String((jrPage - 1) * jrSize + idx + 1).padStart(2, '0')}
                          </td>
                          <td style={td}>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                              <Avatar src={r.reporter_avatar} name={r.reporter_name} size={32}/>
                              <span style={{ fontSize: 13, fontWeight: 500 }}>{r.reporter_name}</span>
                            </div>
                          </td>
                          <td style={{ ...td, maxWidth: 200, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', fontWeight: 500 }}>{r.job_title}</td>
                          <td style={td}><span style={{ padding: '3px 10px', borderRadius: 20, fontSize: 12, fontWeight: 600, background: '#FEF3C7', color: '#92400E', whiteSpace: 'nowrap' }}>{capitalize(r.reason)}</span></td>
                          <td style={td}><span style={{ padding: '3px 10px', borderRadius: 20, fontSize: 12, fontWeight: 600, background: ss.bg, color: ss.color, whiteSpace: 'nowrap' }}>{ss.label}</span></td>
                          <td style={{ ...td, color: SLATE, fontSize: 13, whiteSpace: 'nowrap' }}>{fmt(r.created_at)}</td>
                          <td style={{ ...td, textAlign: 'right' }}>
                            <button
                              onClick={e => { e.stopPropagation(); setResponseTarget(r); }}
                              style={{ padding: '6px 14px', borderRadius: 8, border: `1px solid ${ORANGE}`, background: '#fff', color: ORANGE, fontSize: 12, fontWeight: 600, cursor: 'pointer', fontFamily: 'inherit', whiteSpace: 'nowrap' }}>
                              {r.admin_response ? 'Update' : 'Respond'}
                            </button>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              ) : (
                <table style={{ width: '100%', borderCollapse: 'collapse', minWidth: 700 }}>
                  <thead>
                    <tr>
                      <th style={{ ...th, width: 52, textAlign: 'center' }}>#</th>
                      <th style={th}>Reporter</th>
                      <th style={th}>Reason</th>
                      <th style={th}>Note</th>
                      <th style={th}>Conversation</th>
                      <th style={th}>Reported</th>
                    </tr>
                  </thead>
                  <tbody>
                    {pagedMR.length === 0 ? (
                      <tr><td colSpan={6} style={{ ...td, textAlign: 'center', color: '#94A3B8', padding: '48px 0' }}>
                        {search || reasonF !== 'all' ? 'No reports match your filters.' : 'No message reports yet.'}
                      </td></tr>
                    ) : pagedMR.map((r, idx) => (
                      <tr key={r.id} onClick={() => setDrawerTarget(r)}
                        onMouseEnter={e => e.currentTarget.style.background = BG}
                        onMouseLeave={e => e.currentTarget.style.background = '#fff'}
                        style={{ transition: 'background 0.1s', cursor: 'pointer' }}>
                        <td style={{ ...td, textAlign: 'center', color: '#94A3B8', fontSize: 12 }}>
                          {String((mrPage - 1) * mrSize + idx + 1).padStart(2, '0')}
                        </td>
                        <td style={td}>
                          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                            <Avatar src={r.reporter_avatar} name={r.reporter_name} size={32}/>
                            <span style={{ fontSize: 13, fontWeight: 500 }}>{r.reporter_name}</span>
                          </div>
                        </td>
                        <td style={td}><span style={{ padding: '3px 10px', borderRadius: 20, fontSize: 12, fontWeight: 600, background: '#FEF3C7', color: '#92400E', whiteSpace: 'nowrap' }}>{capitalize(r.reason)}</span></td>
                        <td style={{ ...td, maxWidth: 200, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', color: SLATE, fontSize: 13 }}>{r.note ?? <span style={{ color: '#CBD5E1' }}>—</span>}</td>
                        <td style={{ ...td, fontSize: 12, color: SLATE, fontFamily: 'monospace' }}>{r.conversation_key ?? r.conversation_id?.slice(0, 12).toUpperCase() ?? '—'}</td>
                        <td style={{ ...td, color: SLATE, fontSize: 13, whiteSpace: 'nowrap' }}>{fmt(r.created_at)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>

            {/* pagination */}
            {tab === 'job_reports' ? (
              <Pagination page={jrPage} totalPages={jrTotalPages} pageSize={jrSize} totalItems={filteredJR.length}
                onPage={setJrPage} onPageSize={n => { setJrSize(n); setJrPage(1); }}/>
            ) : (
              <Pagination page={mrPage} totalPages={mrTotalPages} pageSize={mrSize} totalItems={filteredMR.length}
                onPage={setMrPage} onPageSize={n => { setMrSize(n); setMrPage(1); }}/>
            )}
          </>
        )}
      </div>

      {/* modals */}
      {responseTarget && (
        <ResponseModal report={responseTarget} onClose={() => setResponseTarget(null)} onSave={handleSaveResponse}/>
      )}
      {drawerTarget && (
        <DetailDrawer report={drawerTarget} type={tab} onClose={() => setDrawerTarget(null)}/>
      )}
    </div>
  );
};

export default ReportsPage;
